$path = Join-Path $PSScriptRoot '..\src\screens\ProphetDetailScreen.tsx'
$content = [IO.File]::ReadAllText((Resolve-Path $path), [Text.Encoding]::UTF8)
$old = '{String(part.story||'''').split(/\n\s*\n/).filter(Boolean).map((paragraph:string,index:number)=><Text key={index} style={s.articleText}>{paragraph.trim()}</Text>)}'
$new = '{String(part.story||'''').split(/\r?\n/).map((raw:string,index:number)=>{const line=raw.trim();if(!line)return <View key={index} style={s.articleSpace}/>;if(line.startsWith(''# ''))return <Text key={index} style={s.articleH1}>{line.slice(2).replace(/\*\*/g,'''')}</Text>;if(line.startsWith(''## ''))return <Text key={index} style={s.articleH2}>{line.slice(3).replace(/\*\*/g,'''')}</Text>;if(line.startsWith(''### ''))return <Text key={index} style={s.articleH3}>{line.slice(4).replace(/\*\*/g,'''')}</Text>;if(line.startsWith(''> ''))return <View key={index} style={s.articleQuote}><Text style={s.articleQuoteText}>{line.slice(2).replace(/\*\*/g,'''')}</Text></View>;if(/^[-*] /.test(line))return <View key={index} style={s.articleBulletRow}><Text style={s.articleBullet}>•</Text><Text style={s.articleBulletText}>{line.slice(2).replace(/\*\*/g,'''')}</Text></View>;if(/^\*\*(Qur|Source|Reference)/i.test(line))return <Text key={index} style={s.articleReference}>{line.replace(/\*\*/g,'''')}</Text>;return <Text key={index} style={s.articleText}>{line.replace(/\*\*/g,'''')}</Text>})}'
if (-not $content.Contains($old)) { throw 'Article renderer anchor not found' }
$content = $content.Replace($old,$new)
$content = $content.Replace("articleText:{marginBottom:16,fontSize:15,lineHeight:25,color:'#344B40'},", "articleText:{marginBottom:10,fontSize:15,lineHeight:25,color:'#344B40'},articleSpace:{height:7},articleH1:{marginTop:12,marginBottom:12,fontSize:26,lineHeight:34,fontWeight:'900',color:'#075B3B'},articleH2:{marginTop:18,marginBottom:8,fontSize:21,lineHeight:28,fontWeight:'900',color:'#075B3B'},articleH3:{marginTop:14,marginBottom:7,fontSize:17,lineHeight:24,fontWeight:'800',color:'#176143'},articleQuote:{marginVertical:8,padding:14,borderLeftWidth:4,borderLeftColor:'#C6A64D',backgroundColor:'#FFF9E8'},articleQuoteText:{fontSize:14,lineHeight:23,color:'#5D5439'},articleBulletRow:{flexDirection:'row',marginBottom:8},articleBullet:{width:22,fontSize:17,color:'#087A4D'},articleBulletText:{flex:1,fontSize:14,lineHeight:22,color:'#344B40'},articleReference:{marginVertical:7,fontSize:12,lineHeight:19,fontWeight:'800',color:'#99782A'},")
[IO.File]::WriteAllText((Resolve-Path $path), $content, [Text.UTF8Encoding]::new($false))
